<script setup lang="ts" generic="T extends { id: string }">
import AppButton from '../ui/AppButton.vue';
defineProps<{ rows: T[]; columns: { key: string; label: string; sortable?: boolean }[]; page?: number; pages?: number; total?: number; loading?: boolean; sort?: string; direction?: string }>();
defineEmits<{ page: [value: number]; sort: [key: string] }>();
</script>
<template><div class="table-shell" :aria-busy="loading"><div class="table-scroll"><table><thead><tr><th v-for="column in columns" :key="column.key" :aria-sort="column.sortable && sort === column.key ? (direction === 'asc' ? 'ascending' : 'descending') : undefined"><button v-if="column.sortable" class="sort-button" @click="$emit('sort', column.key)">{{ column.label }} <span aria-hidden="true">{{ sort === column.key ? (direction === 'asc' ? '↑' : '↓') : '↕' }}</span></button><template v-else>{{ column.label }}</template></th></tr></thead><tbody><tr v-if="loading"><td :colspan="columns.length" class="table-empty">Loading records…</td></tr><template v-else><tr v-for="row in rows" :key="row.id"><td v-for="column in columns" :key="column.key"><slot :name="`cell-${column.key}`" :row="row">{{ (row as Record<string, unknown>)[column.key] }}</slot></td></tr><tr v-if="!rows.length"><td :colspan="columns.length" class="table-empty"><slot name="empty">No records found.</slot></td></tr></template></tbody></table></div><div v-if="page !== undefined" class="table-footer"><span>{{ total ?? 0 }} records · Page {{ page }} of {{ Math.max(pages ?? 1, 1) }}</span><div class="button-row"><AppButton variant="secondary" :disabled="page <= 1 || loading" @click="$emit('page', page - 1)">Previous</AppButton><AppButton variant="secondary" :disabled="page >= (pages ?? 1) || loading" @click="$emit('page', page + 1)">Next</AppButton></div></div></div></template>
